(()=>{const DRIVE='https://drive.google.com/drive/folders/1iwuKlMfb8JSLV86ZlbPNQg1ri2Q0CeNl',KEY='rc_music_dj_session_v1',ID='rc-dj-drive-utility-button';const icon='<svg width="17" height="17" viewBox="0 0 87.3 78" aria-hidden="true"><path d="m6.6 66.85 3.85 6.65c.8 1.4 1.95 2.5 3.3 3.3l13.75-23.8h-27.5c0 1.55.4 3.1 1.2 4.5z" fill="#0066da"/><path d="m43.65 25-13.75-23.8c-1.35.8-2.5 1.9-3.3 3.3l-25.4 44a9.06 9.06 0 0 0-1.2 4.5h27.5z" fill="#00ac47"/><path d="M43.65 25 57.4 1.2c1.35.8 2.5 1.9 3.3 3.3l25.4 44c.8 1.4 1.2 2.95 1.2 4.5H59.8z" fill="#ffba00"/><path d="M59.8 52.9H32.3l-13.75 23.8c1.35.8 2.95 1.2 4.5 1.2h46c1.55 0 3.15-.4 4.5-1.2z" fill="#ea4335"/></svg>';function access(){try{return JSON.parse(sessionStorage.getItem(KEY)||localStorage.getItem(KEY)||'null')}catch{return null}}function inPanel(){return location.hash.replace(/^#/,'')==='dj'||[...document.querySelectorAll('h1')].some(x=>/Panel de DJ/i.test(x.textContent||''))}function allowed(){const a=access();if(!a)return false;if(a.role==='admin')return true;const p=String(a.planType||a.plan_type||'').toLowerCase();return ['fifteen','monthly','annual'].includes(p)&&(!a.planExpiresAt&&!a.plan_expires_at||new Date(a.planExpiresAt||a.plan_expires_at).getTime()>Date.now())}function target(){const anchor=[...document.querySelectorAll('button')].find(b=>/Adquirir un plan|Desarrollador/i.test(b.textContent||''));if(anchor)return anchor.parentElement||anchor;const h=[...document.querySelectorAll('h1')].find(x=>/Panel de DJ/i.test(x.textContent||''));return h?.closest('header')||h?.parentElement||document.body}function remove(){document.getElementById(ID)?.remove()}function inject(){if(!inPanel()){remove();return}if(document.getElementById(ID))return;const host=target();if(!host)return;const b=document.createElement('button');b.id=ID;b.type='button';b.className='inline-flex items-center gap-2 rounded-xl border border-turquoise/30 bg-turquoise/10 px-3 py-2 text-xs font-bold text-turquoise transition hover:bg-turquoise/20';b.title='Acceso a Actualización y Utilidades Dj.';b.innerHTML=icon+'<span>Actualización y Utilidades Dj.</span>';b.addEventListener('click',()=>{if(allowed())window.open(DRIVE,'_blank','noopener,noreferrer');else location.href='/assets/planes.html#dj-plans'});host.appendChild(b)}const observer=new MutationObserver(inject);const start=()=>{inject();if(document.body)observer.observe(document.body,{childList:true,subtree:true})};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();addEventListener('hashchange',()=>setTimeout(inject,0))})();
